const b = $input.first().json.body ?? $input.first().json;
if (!b.peca_id) throw new Error('Pedido sem peca_id');
return [{ json: { peca_id: b.peca_id } }];

const peca = $('Buscar peça').first().json;
if (!peca || !peca.id) throw new Error('Peça não encontrada');
if (peca.status !== 'na_fila') throw new Error('Peça ' + peca.id + ' já saiu da fila (status ' + peca.status + ')');

// Tudo aqui é editável na aba Configuração da Galera (galera_config e
// galera_documentos). Os valores padrão só valem se a linha não existir.
const config = {};
for (const { json: c } of $('Buscar configuração').all()) if (c.chave) config[c.chave] = c.valor;
const notaMinima = Number(config.nota_minima ?? 7);
const maxRodadas = Number(config.max_rodadas ?? 3);
const ambiente = config.regras_ambiente ?? 'Você roda numa automação, sem acesso a arquivos nem ferramentas. Entregue direto o resultado final, em português.';

const documentos = $('Buscar documentos').all().map(i => i.json)
  .filter(d => d.id && d.ativo !== false)
  .sort((a, b) => (a.ordem ?? 0) - (b.ordem ?? 0));
const docsDo = (slug) => {
  const meus = documentos.filter(d => (d.agentes || []).includes(slug));
  if (!meus.length) return '';
  return '\n\n# DOCUMENTOS DE CONTEXTO DO LAB\n\n' + meus.map(d => '## ' + d.titulo + '\n\n' + d.conteudo).join('\n\n---\n\n');
};

const prompts = {}, modelos = {}, temperaturas = {}, ativos = {}, nomes = {};
for (const { json: a } of $('Buscar agentes').all()) {
  if (!a.slug) continue;
  prompts[a.slug] = ambiente + '\n\n' + a.prompt + (a.observacoes ? '\n\n## Observações\n' + a.observacoes : '') + docsDo(a.slug);
  modelos[a.slug] = a.modelo || 'anthropic/claude-sonnet-5';
  temperaturas[a.slug] = Number(a.temperatura ?? 0.7);
  ativos[a.slug] = a.ativo;
  nomes[a.slug] = a.nome;
}
for (const s of ['conteudo-redator','conteudo-revisor-editorial','conteudo-publicador']) {
  if (!prompts[s]) throw new Error('Agente ' + s + ' não está em galera_agentes');
}
const briefing = [
  'Cliente: LAB', 'Pauta: ' + peca.pauta, 'Canal: ' + peca.canal, 'Formato: ' + peca.formato,
  'Objetivo: ' + peca.objetivo, 'ICP: ' + peca.icp, 'Dor/origem: ' + peca.dor, 'CTA: ' + peca.cta,
  'Funil: ' + peca.funil, 'Publicação pretendida: ' + peca.data_publicacao, 'ID da peça: ' + peca.id,
  'Regra da nota: avança com nota maior ou igual a ' + notaMinima + '; após ' + maxRodadas + ' rodadas abaixo disso, a esteira para.',
].join('\n');
return [{ json: { peca_id: peca.id, formato: peca.formato, canal: peca.canal, data_publicacao: peca.data_publicacao, briefing, prompts, modelos, temperaturas, ativos, nomes, nota_minima: notaMinima, max_rodadas: maxRodadas } }];

