const ctx = $('Montar contexto').first().json;
const rodada = $runIndex + 1;
const passou = r.nota >= ctx.nota_minima && (r.erros_reprovatorios ?? []).length === 0;
return [{ json: { ...r, rodada, passou, esgotou: !passou && rodada >= ctx.max_rodadas, peca: $('Redator').last().json.output } }];

